using UnityEditor;using UnityEngine;
public static class ImportHudPanel{public static object Run(){AssetDatabase.Refresh();var p="Assets/BokumyakuPrototype/Resources/BokumyakuArt/hud_ink_panel_06.png";var i=(TextureImporter)AssetImporter.GetAtPath(p);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spriteBorder=new Vector4(260,230,260,230);i.maxTextureSize=2048;i.npotScale=TextureImporterNPOTScale.None;i.mipmapEnabled=false;i.alphaIsTransparency=true;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();return "imported sliced ink panel";}}
